package net.officefloor.hq.app.plan;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Pauses the plan from the sheet's today, audited as PLAN_PAUSED; a plan already paused is refused. */
public class PausePlan {
    public void pause(@PathVariable("sheetId") String sheetId, @PathVariable("planId") String planId, @RequestBody PauseRequest request,
            Plans plans, People people, Sheets sheets, Settings settings, Audit audit, ObjectResponse<PlanResponse> response)
            throws InvalidPlanException, ViewerRefusedException {
        PlanPausing.change(sheetId, planId, request, plans, people, sheets, settings, audit, response, true);
    }
}
package net.officefloor.hq.app.plan;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.web.ObjectResponse;

/** Shared by pause and resume: finds the sheet's plan, refuses a change to the state it is already in, records and audits it. */
final class PlanPausing {
    static void change(String sheetId, String planId, PauseRequest request, Plans plans, People people, Sheets sheets, Settings settings,
            Audit audit, ObjectResponse<PlanResponse> response, boolean pause) throws InvalidPlanException, ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        Plan plan;
        try {
            plan = plans.find(Long.parseLong(planId));
        } catch (NumberFormatException e) {
            plan = null;
        }
        if (plan == null || !plan.sheetId().equals(sheetId)) {
            throw new InvalidPlanException("No such plan");
        }
        if (plan.paused() == pause) {
            throw new InvalidPlanException(pause ? "The plan is already paused" : "The plan is not paused");
        }
        Person person = people.find(sheetId, plan.personId());
        LocalDate today = sheets.today(sheetId);
        if (pause) {
            plans.pause(plan.id(), today);
        } else {
            plans.resume(plan.id(), today);
        }
        audit.recordOnCommit((pause ? "PLAN_PAUSED" : "PLAN_RESUMED") + " sheet=" + sheetId + " by=" + request.user()
                + " name=" + (person != null ? person.getName() : "") + " start=" + plan.start());
        response.send(PlanResponse.from(plans.find(plan.id()), today));
    }
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { usePersonAction } from '../people/usePersonAction';
import { plansKey, usePlans, type Plan } from './usePlans';

// The person's plans, each with how many claims it has made so far, its next five dates after the sheet's today and whether it is
// paused (with its pause and resume buttons), and the form that adds one: an amount
// the claim form takes, a start (blank: the sheet's today), every N days (a whole number, at least 1) or
// instead monthly on a day of the month (1 to 31), and an end not before the start. A refusal shows the plan error on the row.
export function PlanControl({ personId }: { personId: string }) {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const plans = usePlans(sheet).filter((p) => p.personId === personId);
  const [amount, setAmount] = useState('');
  const [start, setStart] = useState('');
  const [every, setEvery] = useState('');
  const [day, setDay] = useState('');
  const [end, setEnd] = useState('');
  const queryClient = useQueryClient();
  const once = useSubmitOnce();

  const add = useMutation({
    mutationFn: (body: { amount: string; start: string; every: string; day: string; end: string }) =>
      postJson<Plan>(`/api/sheets/${encodeURIComponent(sheet)}/people/${encodeURIComponent(personId)}/plans`, { ...body, user }),
    onSuccess: () => {
      setAmount('');
      setStart('');
